package ar.com.liftmanager.service;
import ar.com.liftmanager.dto.ApiDtos.*; import ar.com.liftmanager.model.*; import ar.com.liftmanager.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ElevatorService {
 private final ElevatorRepository elevators;private final BuildingService buildingService;private final CurrentUserService current;private final ContractRepository contracts;
 public ElevatorService(ElevatorRepository e,BuildingService b,CurrentUserService c,ContractRepository cr){elevators=e;buildingService=b;current=c;contracts=cr;}
 public List<ElevatorView> list(){AppUser u=current.get();List<Elevator> es=u.getRole()==Role.BUILDING_MANAGER?(u.getBuilding()==null?List.of():elevators.findByBuildingId(u.getBuilding().getId())):elevators.findAll();return es.stream().map(this::view).toList();}
 public Elevator get(Long id){Elevator e=elevators.findById(id).orElseThrow(()->BusinessException.notFound("Ascensor no encontrado"));AppUser u=current.get();if(u.getRole()==Role.BUILDING_MANAGER&&(u.getBuilding()==null||!u.getBuilding().getId().equals(e.getBuilding().getId())))throw BusinessException.forbidden("No podés acceder a este ascensor");return e;}
 public ElevatorView create(Long buildingId,ElevatorRequest r){current.requireAdmin();Elevator e=new Elevator();e.setBuilding(buildingService.get(buildingId));e.setCode(r.code().trim());e.setBrand(r.brand());e.setModel(r.model());return view(elevators.save(e));}
 public ElevatorView updateStatus(Long id,ElevatorStatus status){current.requireAdmin();Elevator e=elevators.findById(id).orElseThrow(()->BusinessException.notFound("Ascensor no encontrado"));e.setStatus(status);return view(elevators.save(e));}
 public ContractView createContract(Long elevatorId,ContractRequest r){current.requireAdmin();Elevator e=elevators.findById(elevatorId).orElseThrow(()->BusinessException.notFound("Ascensor no encontrado"));if(r.endDate().isBefore(r.startDate()))throw BusinessException.badRequest("La fecha de fin no puede ser anterior al inicio");if(contracts.findByElevatorIdOrderByEndDateDesc(elevatorId).stream().anyMatch(c->c.isActive()&&!c.getEndDate().isBefore(java.time.LocalDate.now(java.time.ZoneId.of("America/Argentina/Buenos_Aires")))))throw BusinessException.conflict("El ascensor ya tiene un contrato vigente");MaintenanceContract c=new MaintenanceContract();c.setElevator(e);c.setStartDate(r.startDate());c.setEndDate(r.endDate());c.setMonthlyFee(r.monthlyFee());return contractView(contracts.save(c));}
 private ElevatorView view(Elevator e){return new ElevatorView(e.getId(),e.getCode(),e.getBrand(),e.getModel(),e.getStatus(),e.getBuilding().getId(),e.getBuilding().getName());}
 private ContractView contractView(MaintenanceContract c){return new ContractView(c.getId(),c.getElevator().getId(),c.getStartDate(),c.getEndDate(),c.getMonthlyFee(),c.isActive());}
}
